#include <stdio.h>
#include <stdlib.h>

typedef struct tree {
  struct tree *left, *right;
} tree;

static tree *bottom_up_tree(int item, int depth) {
  tree *t = malloc(sizeof(tree));
  if (depth > 0) {
    t->left = bottom_up_tree(item, depth - 1);
    t->right = bottom_up_tree(item + 1, depth - 1);
  } else {
    t->left = t->right = NULL;
  }
  return t;
}

static int item_check(tree *t) {
  if (t->left == NULL) return 1;
  return 1 + item_check(t->left) + item_check(t->right);
}

static void free_tree(tree *t) {
  if (t->left != NULL) {
    free_tree(t->left);
    free_tree(t->right);
  }
  free(t);
}

int main(int argc, char **argv) {
  int n = argc > 1 ? atoi(argv[1]) : 20;
